package contextmeter

import "math"

// BarWidth is the default width of the status-bar context meter.
const BarWidth = 10

// Severity classifies context usage into Hermes-compatible display buckets.
type Severity int

const (
	SeverityDim Severity = iota
	SeverityGood
	SeverityWarn
	SeverityBad
	SeverityCritical
)

// ClampPercent normalizes context percentages before rendering bars or labels
// so every status-bar surface reports the same bounded value.
func ClampPercent(pct float64) float64 {
	if math.IsNaN(pct) || pct < 0 {
		return 0
	}
	if pct > 100 {
		return 100
	}
	return pct
}

// PercentFromTokens converts token usage to a rounded, bounded percentage.
func PercentFromTokens(tokens, length int) *int {
	if length <= 0 {
		return nil
	}
	pct := int((float64(tokens) / float64(length) * 100) + 0.5)
	if pct < 0 {
		pct = 0
	}
	if pct > 100 {
		pct = 100
	}
	return &pct
}

// FilledCells returns the rounded number of filled cells for BarWidth.
func FilledCells(pct float64) int {
	pct = ClampPercent(pct)
	filled := int((pct/100)*float64(BarWidth) + 0.5)
	if filled < 0 {
		return 0
	}
	if filled > BarWidth {
		return BarWidth
	}
	return filled
}

// SeverityForPercent mirrors Hermes' _status_bar_context_style: nil → dim,
// <50 good, 50–80 warn, 81–94 bad, ≥95 critical.
func SeverityForPercent(percent *int) Severity {
	if percent == nil {
		return SeverityDim
	}
	return SeverityForFloat(float64(*percent))
}

// SeverityForFloat returns severity for already-computed percentage values.
func SeverityForFloat(pct float64) Severity {
	pct = ClampPercent(pct)
	switch {
	case pct >= 95:
		return SeverityCritical
	case pct > 80:
		return SeverityBad
	case pct >= 50:
		return SeverityWarn
	default:
		return SeverityGood
	}
}

package hermes

import (
	"fmt"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/statusbar/contextmeter"
	"github.com/charmbracelet/lipgloss"
)

// Model is the pure input to the Hermes-compatible status bar renderer.
// It carries the data Hermes' cli.py:_get_status_bar_snapshot produces in
// Python — model name, token usage, session duration in seconds, and
// per-prompt elapsed seconds — without coupling to Bubble Tea, providers, or
// wall-clock IO.
type Model struct {
	StatusLabel     string
	ModelName       string
	ReasoningEffort string
	Fast            bool
	ContextTokens   int
	ContextLength   int
	SessionDuration int64
	// PromptElapsed is the per-prompt elapsed time in seconds. Only rendered
	// in the wide tier when HasPromptElapsed is true.
	PromptElapsed    int64
	PromptLive       bool
	HasPromptElapsed bool
	CWDLabel         string
}

// ContextSeverity classifies the context-usage percent into the same five
// buckets Hermes' status bar uses to colour the percentage label.
type ContextSeverity = contextmeter.Severity

const (
	ContextDim      ContextSeverity = contextmeter.SeverityDim
	ContextGood     ContextSeverity = contextmeter.SeverityGood
	ContextWarn     ContextSeverity = contextmeter.SeverityWarn
	ContextBad      ContextSeverity = contextmeter.SeverityBad
	ContextCritical ContextSeverity = contextmeter.SeverityCritical
)

// ContextSeverityFor mirrors Hermes' _status_bar_context_style: nil → dim,
// <50 good, 50–80 warn, 81–94 bad, ≥95 critical.
func ContextSeverityFor(percent *int) ContextSeverity {
	return contextmeter.SeverityForPercent(percent)
}

// Render renders the single-line Hermes-compatible status rule for the given
// width. The row follows current Hermes Ink's StatusRule shape: a leading
// rule/status segment, bar-separated model/usage details, and an optional cwd
// label on the right. Width tiers keep the row readable on small terminals and
// output is trimmed with an ellipsis so it never wraps.
func Render(model Model, width int) string {
	if width <= 0 {
		return ""
	}
	status := strings.TrimSpace(model.StatusLabel)
	if status == "" {
		status = "ready"
	}
	short := ModelLabel(model.ModelName, model.ReasoningEffort, model.Fast)
	duration := DurationLabel(model.SessionDuration)
	percent := Percent(model.ContextTokens, model.ContextLength)
	percentLabel := "--"
	if percent != nil {
		percentLabel = fmt.Sprintf("%d%%", *percent)
	}

	parts := []string{status, short}
	switch {
	case width < 52:
		parts = append(parts, duration)
	case width < 76:
		parts = append(parts, percentLabel, duration)
	default:
		var contextLabel string
		if model.ContextLength > 0 {
			contextLabel = fmt.Sprintf("%s/%s",
				FormatTokenCount(model.ContextTokens),
				FormatContextLength(model.ContextLength),
			)
		} else {
			contextLabel = "ctx --"
		}
		parts = append(parts, contextLabel)
		if percent != nil {
			parts = append(parts, fmt.Sprintf("[%s] %s", ContextBar(*percent), percentLabel))
		} else {
			parts = append(parts, percentLabel)
		}
		parts = append(parts, duration)
		if model.HasPromptElapsed {
			parts = append(parts, PromptElapsed(model.PromptElapsed, model.PromptLive))
		}
	}

	line := "─ " + strings.Join(parts, " │ ")
	if cwd := strings.TrimSpace(model.CWDLabel); cwd != "" && width >= 76 {
		line += " ─ " + cwd
	}
	return TrimToWidth(line, width)
}

func ModelLabel(name, effort string, fast bool) string {
	if name == "" {
		return "unknown"
	}
	if i := strings.LastIndex(name, "/"); i >= 0 {
		name = name[i+1:]
	}
	if strings.HasSuffix(name, ".gguf") {
		name = strings.TrimSuffix(name, ".gguf")
	}
	name = strings.TrimPrefix(name, "claude-")
	name = strings.TrimPrefix(name, "claude_")
	name = strings.TrimPrefix(name, "anthropic-")
	name = strings.TrimPrefix(name, "anthropic_")
	name = strings.NewReplacer("-", " ", "_", " ").Replace(name)
	name = strings.TrimSpace(name)
	pieces := []string{name}
	if e := effortLabel(effort); e != "" {
		pieces = append(pieces, e)
	}
	if fast {
		pieces = append(pieces, "fast")
	}
	label := strings.Join(pieces, " ")
	if lipgloss.Width(label) > 26 {
		label = TrimToWidth(label, 26)
	}
	return label
}

func effortLabel(effort string) string {
	value := strings.ToLower(strings.TrimSpace(effort))
	switch value {
	case "", "medium", "normal", "default":
		return ""
	default:
		return value
	}
}

func ContextBar(percent int) string {
	filled := contextmeter.FilledCells(float64(percent))
	return strings.Repeat("█", filled) + strings.Repeat("░", contextmeter.BarWidth-filled)
}

func DurationLabel(seconds int64) string {
	if seconds < 60 {
		return fmt.Sprintf("%ds", seconds)
	}
	minutesF := float64(seconds) / 60
	if minutesF < 60 {
		return fmt.Sprintf("%dm", roundHalfAwayFromZero(minutesF))
	}
	hoursF := minutesF / 60
	if hoursF < 24 {
		hours := int(hoursF)
		remMin := int(minutesF) % 60
		if remMin == 0 {
			return fmt.Sprintf("%dh", hours)
		}
		return fmt.Sprintf("%dh %dm", hours, remMin)
	}
	days := hoursF / 24
	return fmt.Sprintf("%.1fd", days)
}

func roundHalfAwayFromZero(v float64) int {
	if v >= 0 {
		return int(v + 0.5)
	}
	return int(v - 0.5)
}

func Percent(tokens, length int) *int {
	return contextmeter.PercentFromTokens(tokens, length)
}

func FormatTokenCount(value int) string {
	abs := value
	sign := ""
	if abs < 0 {
		abs = -abs
		sign = "-"
	}
	if abs < 1_000 {
		return fmt.Sprintf("%s%d", sign, abs)
	}
	for _, unit := range []struct {
		threshold int
		suffix    string
	}{
		{1_000_000_000, "B"},
		{1_000_000, "M"},
		{1_000, "K"},
	} {
		if abs >= unit.threshold {
			scaled := float64(abs) / float64(unit.threshold)
			var text string
			switch {
			case scaled < 10:
				text = fmt.Sprintf("%.2f", scaled)
			case scaled < 100:
				text = fmt.Sprintf("%.1f", scaled)
			default:
				text = fmt.Sprintf("%.0f", scaled)
			}
			text = trimTrailingZeros(text)
			return sign + text + unit.suffix
		}
	}
	return fmt.Sprintf("%s%d", sign, abs)
}

func FormatContextLength(tokens int) string {
	if tokens >= 1_000_000 {
		val := float64(tokens) / 1_000_000
		rounded := float64(int(val + 0.5))
		if abs(val-rounded) < 0.05 {
			return fmt.Sprintf("%dM", int(rounded))
		}
		return fmt.Sprintf("%.1fM", val)
	}
	if tokens >= 1_000 {
		val := float64(tokens) / 1_000
		rounded := float64(int(val + 0.5))
		if abs(val-rounded) < 0.05 {
			return fmt.Sprintf("%dK", int(rounded))
		}
		return fmt.Sprintf("%.1fK", val)
	}
	return fmt.Sprintf("%d", tokens)
}

func PromptElapsed(seconds int64, live bool) string {
	emoji := "⏲"
	if live {
		emoji = "⏱"
	}
	if seconds <= 0 {
		return emoji + " 0s"
	}
	days := seconds / 86400
	rem := seconds % 86400
	hours := rem / 3600
	rem %= 3600
	minutes := rem / 60
	secs := rem % 60
	switch {
	case days > 0:
		return fmt.Sprintf("%s %dd %dh %dm", emoji, days, hours, minutes)
	case hours > 0:
		if secs > 0 {
			return fmt.Sprintf("%s %dh %dm %ds", emoji, hours, minutes, secs)
		}
		return fmt.Sprintf("%s %dh %dm", emoji, hours, minutes)
	case minutes > 0:
		if secs > 0 {
			return fmt.Sprintf("%s %dm %ds", emoji, minutes, secs)
		}
		return fmt.Sprintf("%s %dm", emoji, minutes)
	default:
		return fmt.Sprintf("%s %ds", emoji, secs)
	}
}

func TrimToWidth(text string, maxWidth int) string {
	if maxWidth <= 0 {
		return ""
	}
	if lipgloss.Width(text) <= maxWidth {
		return text
	}
	const ellipsis = "..."
	ellipsisWidth := lipgloss.Width(ellipsis)
	if maxWidth <= ellipsisWidth {
		out := ""
		w := 0
		for _, r := range ellipsis {
			rw := lipgloss.Width(string(r))
			if w+rw > maxWidth {
				break
			}
			out += string(r)
			w += rw
		}
		return out
	}
	var b strings.Builder
	used := 0
	for _, r := range text {
		rw := lipgloss.Width(string(r))
		if used+rw+ellipsisWidth > maxWidth {
			break
		}
		b.WriteRune(r)
		used += rw
	}
	return strings.TrimRight(b.String(), " \t") + ellipsis
}

func trimTrailingZeros(s string) string {
	if !strings.Contains(s, ".") {
		return s
	}
	s = strings.TrimRight(s, "0")
	s = strings.TrimRight(s, ".")
	return s
}

func abs(x float64) float64 {
	if x < 0 {
		return -x
	}
	return x
}

package indicators

import (
	"fmt"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/tui/statusbar/contextmeter"
)

// faceTickerIndicators maps task states to their cycling face indicators.
// These cycle based on frame number to provide visual feedback.
var faceTickerIndicators = []string{"⚕", "🌀", "🤔", "✨", "🍵", "🔮"}

// RenderFaceTicker returns a cycling status indicator based on state and frame.
// The indicator cycles through ⚕🌀🤔✨🍵🔮 based on frame mod 6. Different states
// may map to different starting positions in the cycle.
func RenderFaceTicker(state string, frame int) string {
	return faceTickerIndicators[faceTickerPosition(state, frame)]
}

func faceTickerPosition(state string, frame int) int {
	return positiveModulo(stateOffset(state)+frame, len(faceTickerIndicators))
}

func stateOffset(state string) int {
	state = normalizeFaceTickerState(state)
	switch state {
	case "idle":
		return 0
	case "reasoning":
		return 1
	case "working":
		return 2
	case "waiting":
		return 3
	case "ready":
		return 4
	case "break":
		return 5
	case "magic":
		return 0
	case "error":
		return 2
	default:
		hash := 0
		for _, c := range state {
			hash += int(c)
		}
		return positiveModulo(hash, len(faceTickerIndicators))
	}
}

func normalizeFaceTickerState(state string) string {
	return strings.ToLower(strings.TrimSpace(state))
}

func positiveModulo(value, modulus int) int {
	if modulus <= 0 {
		return 0
	}
	position := value % modulus
	if position < 0 {
		position += modulus
	}
	return position
}

// RenderContextBar renders a filled █ and empty ░ bar representing the
// percentage with severity-based coloring semantics. It returns a 10-character
// string like "████░░░░░░" for 40%.
func RenderContextBar(pct float64) string {
	filled := contextmeter.FilledCells(pct)
	return strings.Repeat("█", filled) + strings.Repeat("░", contextmeter.BarWidth-filled)
}

// ContextBarSeverity returns the severity level for a given percentage.
func ContextBarSeverity(pct float64) contextmeter.Severity {
	return contextmeter.SeverityForFloat(pct)
}

// RenderContextBarWithLabel renders a context bar with a percentage label.
func RenderContextBarWithLabel(pct float64) string {
	pct = contextmeter.ClampPercent(pct)
	bar := RenderContextBar(pct)
	return fmt.Sprintf("[%s] %d%%", bar, int(pct))
}

package modes

import "strings"

// Mode controls where the Hermes-compatible status rule renders.
type Mode string

const (
	ModeTop    Mode = "top"
	ModeBottom Mode = "bottom"
	ModeOff    Mode = "off"
)

const SlashUsage = "usage: /statusbar [on|off|top|bottom|toggle]"

func Normalize(mode Mode) Mode {
	switch mode {
	case ModeTop, ModeBottom, ModeOff:
		return mode
	default:
		return ModeTop
	}
}

func SlashNext(input string, current Mode) (Mode, bool) {
	current = Normalize(current)
	fields := strings.Fields(strings.TrimSpace(input))
	if len(fields) <= 1 {
		return Toggled(current), true
	}
	if len(fields) > 2 {
		return current, false
	}
	switch strings.ToLower(fields[1]) {
	case "on", "top":
		return ModeTop, true
	case "bottom":
		return ModeBottom, true
	case "off":
		return ModeOff, true
	case "toggle":
		return Toggled(current), true
	default:
		return current, false
	}
}

func Toggled(current Mode) Mode {
	if Normalize(current) == ModeOff {
		return ModeTop
	}
	return ModeOff
}

package statusbar

import "github.com/TrebuchetDynamics/gormes-agent/internal/tui/statusbar/hermes"

// HermesModel is the pure input to the Hermes-compatible status bar renderer.
type HermesModel = hermes.Model

// HermesContextSeverity classifies context usage for Hermes-compatible status bars.
type HermesContextSeverity = hermes.ContextSeverity

const (
